import jax
import jax.numpy as jnp
from jax import random


def draw(key):
    a, b = random.split(key)
    return random.normal(a) + random.normal(b)


def sample_batch(keys):
    if keys.shape[0] == 0:
        return jnp.empty((0,), dtype=jnp.float32)
    return jax.vmap(draw)(keys)

